cat > App.swift <<'EOF'
import SwiftUI

@main
struct RunnerApp: App {
    var body: some Scene {
        WindowGroup {
            Text("UI Test Runner")
        }
    }
}
EOF
cat > UITests.swift <<'EOF'
import XCTest

final class RunnerUITests: XCTestCase {
    func testFilterRoomsForBook() {
        let app = XCUIApplication(bundleIdentifier: "im.vector.app")
        app.activate()

        let search = app.searchFields.firstMatch
        if search.waitForExistence(timeout: 8) {
            search.tap()
            search.typeText("Book")
        } else {
            let textField = app.textFields.firstMatch
            XCTAssertTrue(textField.waitForExistence(timeout: 5), "Room search field not found. UI: \(app.debugDescription)")
            textField.tap()
            textField.typeText("Book")
        }

        XCTAssertTrue(app.staticTexts["Book Club"].waitForExistence(timeout: 5), "Filtered room not found. UI: \(app.debugDescription)")
    }
}
EOF
